TLM.f("Sancti/05-09",{"officium":"S. Gregorii Nazianzeni Episcopi Confessoris Ecclesiæ Doctoris","rule":["vide C4a;","Gloria","CredoDA"],"ruleInherited":["Gloria"],"fallback":"Commune/C4a","from":{"Introitus":"Commune/C4a","Graduale":"Commune/C4a","GradualeP":"Commune/C4a","Tractus":"Commune/C4a","Evangelium":"Commune/C4a","Offertorium":"Commune/C4a","Secreta":"Commune/C4a","Communio":"Commune/C4a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui pópulo tuo aetérnae salútis beátum Gregórium minístrum tribuísti: praesta, quaésumus; ut, quem Doctórem vitae habúimus in terris, intercessórem habére mereámur in caelis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 39:6-14"},{"k":"text","la":"Justus cor suum tradet ad vigilándum dilúculo ad Dóminum, qui fecit illum, et in conspéctu Altíssimi deprecábitur. Apériet os suum in oratióne, et pro delíctis suis deprecábitur. Si enim Dóminus magnus volúerit, spíritu intellegéntias replébit illum: et ipse tamquam imbres mittet elóquia sapiéntiæ suæ, et in oratióne confitébitur Dómino: et ipse díriget consílium ejus et disciplínam, et in abscónditis suis consiliábitur. Ipse palam fáciet disciplínam doctrínæ suæ, et in lege testaménti Dómini gloriábitur. Collaudábunt multi sapiéntiam ejus, et usque in sǽculum non delébitur. Non recédet memória ejus, et nomen ejus requirétur a generatióne in generatiónem. Sapiéntiam ejus enarrábunt gentes, et laudem ejus enuntiábit ecclésia."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est, multiplicábitur. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti Gregóri Pontíficis tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Ut nobis, Dómine, tua sacrifícia dent salútem: beátus Gregórius Póntifex tuus et Doctor egrégius, quaésumus, precátor accédat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"c970c462bacf8f65":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. <i>Aleluja</i>, <i>aleluja</i>.\n(Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. <i>Aleluja</i>, <i>aleluja</i>.","kn":"(Crkv. 15, 5). Usred Crkve otvorio je Gospodin njegova usta i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave (Aleluja, aleluja). (Ps. 91, 2.) Dobro je slaviti Gospodina i pjevati Imenu Tvomu,^ Višnji! Slava Ocu... Usred Crkve.., <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"86ac317bae30b81d":{"t":"<i>Pomolimo se</i>.\nBože, koji si svome puku dao blaženoga Grgura za vođu na putu vječnoga spasenja, daj molimo, da zavrijedimo da nam na nebesima bude zagovornik onaj koji nam je na zemlji bio naučitelj života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si htio, da blaženi I. bude Tvomu puku vodič na putu spasa, podaj, molimo, da zavri jedimo imati za nebeskog zaštitnika onoga, koji nam je na zemlji bio učitelj života, po G. n.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"087346353430085a":{"t":"Sir 39, 6-14\nČitanje knjige Mudrosti. Pravednik jutrom rano diže srce svoje da bdije pred Gospodinom Stvoriteljem svojim i moli se pred licem Svevišnjega. Otvara usta svoja u molitvi i moli za oproštenje grijeha svojih. A veliki Gospodin, kad mu se svidi, napunja ga duhom shvaćanja, te on kao kiša izlijeva riječi svoje mudrosti i u molitvi slavi Gospodina. Ispunja njegove odluke i nauku i bavi se istraživanjem otajstava njegovih. Očigledno pokazuje vrijednost svoje nauke i hvali se zakonom zavjeta Gospodnjega. Mnogi će slaviti mudrost njegovu i neće se zaboraviti dovijeka. Neće nestati njegove uspomene, a ime će mu se spominjati od koljena do koljena. Narodi će pripovijedati o njegovoj mudrosti, a hvalu će mu Crkva naviještati.","kn":"Čitanje Knjige mudrosti (Crkv. 39, 6-14). Pravednik će se truditi, da porani do Gospodina, koji ga je stvorio, i uzdizat će .svoje molitve pred Svevišnjim. Otvorit će na molitvu svoja usta i skrušlt će se za svoje prestupke. Ako bude htio, veliki Gospodin, napunit će ga duhom razuma, a on će riječi svoje mudrosti izliti kao kišu i molitvom će slaviti Gospodina. On će sam upravljati injegovim nakanama i znanjem, da razmišlja o njegovim tajnama. Objavit će pouke njegove nauke ,1 proslavit će se u zakonu Božjega zavjeta. Mnogi će hvaliti njegovu mudrost i ne će biti .nikada zaboravljen. Uspomene na njega ne će nestati, i .njegovo će se ime slaviti od naraštaja do naraštaja. Narodi će slaviti njegovu mudrost, a zbor vjernik.a širit će njegovu slavu.","knRef":"Kniewald 1942, str. 526–527 (snimka 264) (OCR)"},"ef86f28d488eaa31":{"t":"Sir 45, 9, Hoš 14, 6\n<i>Aleluja</i>, <i>aleluja</i>.\n(Sir 45,9) Gospodin ga je ljubio i ukrasio, zaodjenuo ga je haljinom slave. <i>Aleluja</i>.\n(Hoš 14, 6) Pravednik raste kao ljiljan i vječno cvate pred Gospodinom. <i>Aleluja</i>.","kn":"Aleluja, aleluja. (Crkv. 45, 9) Gospodin ga je ljubio i ukra.sio, zaodjenuo ga je haljinom slave, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"a220bcd1476c8c48":{"t":"Mt 5, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Vi ste sol zemlje. Ako sol izvjetri, čim će se soliti? Za ništa više ne vrijedi, nego da se izbaci i da je ljudi pogaze. Vi ste svjetlo svijeta. Ne može se sakriti grad sazidan na gori. Niti se upaljuje svijeća i postavlja pod varićak, nego na svijećnjak da svijetli svima koji su u kući. Tako neka svijetli vaše svjetlo pred ljudima da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti da sam došao ukinuti zakon ili proroke! Nisam došao ukinuti nego dopuniti. Zaista vam kažem, dok stoji nebo i zemlja, neće od zakona nestati ni jednog slova, niti jednog znaka, dok se sve ne ispuni. Tko, dakle, dokine jednu od ovih najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom. A tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom.","kn":"t Slijedi sveto evanđelje po Mateju (5, 13-19). U ono vrijeme reče Isus svojim učenicima: Vi ste sol ze^ji. Ako se sol pokvari, čim će se soliti? Nije više ni zašto, nego da se baci van, da je pogaze ljudi. Vi ste svijetlo svijetu. Ne može se sakriti na gori sazidan grad. Niti se upaljuje svijetlo i po- stavlja pod posudu, nego na svijećnjak, da svijetli svima u kući. Tako neka svijetli vaše svijetlo pred ljudima, da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti, da sam došao ukinuti zakon ili proroke! Nijesam došao ukinuti, nego dopuniti. Zaista vam kažem, dok ne prođe nebo i zemlja, ne će od zakona nestati ni jednoga slova ni jednoga znaka, dok se ne ispuni sve. Tko, 'dakle, dokine jednu od ovUi najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom, a tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"5df0301ba9f14238":{"t":"Ps 91, 13\nPravednik cvate kao palma i raste kao libanski cedar. <i>Aleluja</i>.","kn":"(Ps. 91, 13). Pravednik cvate poput paome i raste poput libanonskog cedra, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 814–815 (snimka 408) (OCR)"},"2a4e99b13d3c96bb":{"t":"Neka nam, Gospodine, pomogne pobožna molitva svetoga Grgura tvoga biskupa i naučitelja, i neka njegova molitva učini da ti naši darovi budu prijatni i isprosi nam oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka nam. Gospodine, sveti Petar, biskup Tvoj i naučitelj, ne uskrati svoje pobožne molitve, nego neka svojom molitvom naše darove učini Tebi prijatnima,, a nama neka uvijek pribavlja Tvoje oprošten je. Po G. n. ,","knRef":"Kniewald 1942, str. 512–513 (snimka 257) (OCR)"},"1a0a565aa39e4fe3":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>u ovo</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"j Uistinu je dostojno i pravedno, pravo i spaso- I doba, ali osobito svečano na - današnji dan, (u ovo vrijeme), kad je žrtvovano naše vazmeno Janje, I Isukrst; jer On je pravo janje, koje je uzelo grijehe : svojim je uskrsnućem obnovio naš ž^vot. Zato pje- I vamo pjesmu Tvoje slave s anđelima i s arkanđe lima, s. prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"18d15f4c3171d6cb":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada. <i>Aleluja</i>.","kn":"(Lk. 12, 42). Evo razboritog i vjernog upravitelja, koga postavi Gospodin nad družinom svojom, da im na vrijeme daje hranu, koja im pripada, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"bb75ea65a343d5ff":{"t":"<i>Pomolimo se</i>.\nNeka se zauzme za nas, molimo, Gospodine, blaženi Grgur tvoj biskup i naučitelj, da nam tvoje žrtve donesu spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"e3481c16f40c8803":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – On se poslije svojeg uskrsnuća svim svojim učenicima javno ukazao i pred njihovim se očima uzdigao na nebo, da nas učini dionicima svoga božanstva. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, jer On se poslije svoga uskrsnuća očito ukazao svim svojim učenicima 1 njima se na očigled uzđignuo na nebo, da tako, po njegovom daru, budemo zajedničari Božanstva Njegova. I toga radi pjevamo pjesmu slave Tvoje s anđelima i B arkanđelima, s prijestolima i s gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 336–337 (snimka 169) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. Allelúja, allelúja."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. Allelúja, allelúja."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum. Allelúja."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus qui in domo sunt. Sic lúceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus, quæ in Líbano est multiplicábitur. Allelúja."}],"Secreta":[{"k":"rubric","la":"Pro Doctore Pontifice"},{"k":"text","la":"Sancti Gregóri Pontíficis tui atque Doctóris nobis, Dómine, pia non desit orátio: quæ et múnera nostra concíliet; et tuam nobis indulgéntiam semper obtíneat."},{"k":"macro","name":"Per Dominum"}]}}});
